<script>const prod=document.getElementById('pcProduct'),std=document.getElementById('pcStandard'),target=document.getElementById('pcTarget');prod.addEventListener('change',()=>{if(prod.selectedOptions[0].dataset.standard)std.value=prod.selectedOptions[0].dataset.standard;calc()});function calc(){let n=Number(target.value)*Number(std.value);document.getElementById('pcEstimate').textContent=n>0?Math.floor(n/3600)+' h '+Math.floor(n%3600/60)+' min '+Math.round(n%60)+' s':'—'}target.addEventListener('input',calc);std.addEventListener('input',calc);function addWorker(){let d=document.createElement('div');d.style='display:flex;gap:8px;margin-bottom:8px';d.innerHTML='<input class="pc-field" name="workers[]" required maxlength="150" placeholder="Nombre del operario"><button type="button" class="pc-btn" onclick="this.parentElement.remove()">Quitar</button>';document.getElementById('pcWorkers').appendChild(d)}</script>
